"use client";

import { useEffect, useId, useMemo, useRef, useState } from "react";
import { cx } from "../utils/cx";
import { Dialog, DialogContent, DialogTitle } from "./dialog";

export type CommandItem = {
  id: string;
  label: string;
  /** Shown beside the label and matched by the filter. */
  group?: string;
  /** Extra words the filter matches. */
  keywords?: string;
  disabled?: boolean;
};

export type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  items: CommandItem[];
  /** Called with the chosen item. The palette closes afterwards. */
  onSelect: (item: CommandItem) => void;
  /** Accessible name of the dialog. */
  label?: string;
  placeholder?: string;
  emptyMessage?: string;
  /** Open on Cmd/Ctrl+K (and close on it again). Opt-in so a host app keeps control of its shortcuts. */
  shortcut?: boolean;
  /** Replace the default case-insensitive substring filter. */
  filter?: (item: CommandItem, query: string) => boolean;
  className?: string;
};

const defaultFilter = (item: CommandItem, query: string) =>
  `${item.label} ${item.group ?? ""} ${item.keywords ?? ""}`.toLowerCase().includes(query.toLowerCase());

/**
 * A searchable list of actions or destinations in a top-positioned dialog. The input is a combobox: focus stays in it
 * while Up/Down move the highlighted option (`aria-activedescendant`), Enter chooses it, Escape closes.
 */
export function CommandPalette({
  open,
  onOpenChange,
  items,
  onSelect,
  label = "Command palette",
  placeholder = "Type to search…",
  emptyMessage = "Nothing matches.",
  shortcut,
  filter = defaultFilter,
  className,
}: CommandPaletteProps) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const listId = useId();
  const list = useRef<HTMLDivElement>(null);
  const shown = useMemo(() => {
    const q = query.trim();
    return q ? items.filter((i) => filter(i, q)) : items;
  }, [items, query, filter]);

  useEffect(() => {
    if (!shortcut) return;
    const onKey = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        e.preventDefault();
        onOpenChange(!open);
      }
    };
    addEventListener("keydown", onKey);
    return () => removeEventListener("keydown", onKey);
  }, [shortcut, open, onOpenChange]);

  useEffect(() => {
    if (!open) {
      setQuery("");
      setActive(0);
    }
  }, [open]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: scroll when the highlight or the result list changes
  useEffect(() => {
    list.current?.querySelector('[aria-selected="true"]')?.scrollIntoView?.({ block: "nearest" });
  }, [active, shown]);

  const choose = (item: CommandItem | undefined) => {
    if (!item || item.disabled) return;
    onSelect(item);
    onOpenChange(false);
  };
  const optionId = (i: number) => `${listId}-${i}`;
  const move = (dir: 1 | -1) => {
    if (!shown.length) return;
    let i = active;
    for (let n = 0; n < shown.length; n++) {
      i = (i + dir + shown.length) % shown.length;
      if (!shown[i]?.disabled) break;
    }
    setActive(i);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent position="top" className={cx("hm-palette", className)}>
        <DialogTitle className="hm-sr-only">{label}</DialogTitle>
        <input
          className="hm-palette-input"
          type="text"
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={shown.length ? optionId(active) : undefined}
          aria-label={label}
          placeholder={placeholder}
          autoComplete="off"
          spellCheck={false}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") move(1);
            else if (e.key === "ArrowUp") move(-1);
            else if (e.key === "Home") setActive(0);
            else if (e.key === "End") setActive(Math.max(0, shown.length - 1));
            else if (e.key === "Enter") choose(shown[active]);
            else return;
            e.preventDefault();
          }}
        />
        <div ref={list} id={listId} role="listbox" aria-label={label} className="hm-palette-list">
          {shown.map((item, i) => (
            // biome-ignore lint/a11y/useKeyWithClickEvents: keyboard is handled by the combobox input (aria-activedescendant)
            <div
              key={item.id}
              id={optionId(i)}
              role="option"
              aria-selected={i === active}
              aria-disabled={item.disabled || undefined}
              className="hm-palette-option"
              onClick={() => choose(item)}
              onPointerMove={() => i !== active && !item.disabled && setActive(i)}
            >
              <span>{item.label}</span>
              {item.group ? <small>{item.group}</small> : null}
            </div>
          ))}
        </div>
        {shown.length ? null : (
          <p className="hm-palette-empty" role="status">
            {emptyMessage}
          </p>
        )}
      </DialogContent>
    </Dialog>
  );
}
